fun parseAmount(raw: String): Double? = raw.trim().toDoubleOrNull()
fun isValidExpense(amount: Double, category: String) = amount > 0.0 && category.isNotBlank()
fun summary(amount: Double, category: String) = "$category: £$amount"

fun main() {
    val rawAmount = "9.75"
    val category = "Travel"
    val amount = parseAmount(rawAmount)

    if (amount == null) {
        println("Enter a number")
    } else if (!isValidExpense(amount, category)) {
        println("Invalid expense")
    } else {
        println(summary(amount, category))
    }
}
